import {initial,transition,restore} from './engine.js';
import {englishVoices,chooseVoice,loadVoices} from './speech.js';
import {NPCS,distance,bound,nearest,step,hasInformation,reply} from './world.js';
import {guidance,coachAnswer} from './guidance.js';
let preferredVoice='';try{preferredVoice=localStorage.getItem('campus-voice')||'';}catch{}
let speechRequest=0;
const KEY='campus-quest-v1';let storage=true,s;try{s=restore(localStorage.getItem(KEY));}catch{s=initial();storage=false;}
let view='welcome',subtitles=true,hint=0,message='Hey, explorer! I’m Nova. Ready to find Pip together?',translation='我是 Nova，你的同行教练。你来决定路线，我陪你一起寻找 Pip。',notice='',recording=null,chosen=false,quiz=false,transfer=false;
let player={x:150,y:460},companion={x:115,y:480},destination=null,nearby=null,keys=new Set(),lastFrame=0,lastSave=0,micApproved=false;
let npcLine='',npcZh='',lastQuestion='',heardBy='',micError='';
try{const p=JSON.parse(localStorage.getItem('campus-position'));if(Number.isFinite(p?.x)&&Number.isFinite(p?.y))player=bound(p);}catch{}
nearby=nearest(player);
message=guidance(s).en;translation=guidance(s).zh;let guideHighlight='',coachStatus='';
const places={plaza:{name:'科技节广场',en:'Festival Plaza',icon:'🎪',x:17,y:52},library:{name:'图书馆',en:'Library',icon:'🏛️',x:51,y:46},art:{name:'美术教室',en:'Art Room',icon:'🎨',x:82,y:49},greenhouse:{name:'温室',en:'Greenhouse',icon:'🌿',x:51,y:17},gym:{name:'体育馆',en:'Gym',icon:'🏀',x:51,y:80}};
const clues={witness:['目击记录','Pip went past the library, towards the art room.','Pip 经过图书馆，向美术教室走去。'],record:['设备记录','10:20 — blue light flashing.','10:20，蓝灯闪烁。Pip 追逐明亮物品时会闪蓝灯。'],decoration:['装饰物的去向','We carried a shiny decoration to the greenhouse.','美术社把闪亮的装饰物搬到了温室。']};
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,act,cls='secondary',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${text}</button>`;
function commit(a,v){const prev=guidance(s).en;s=transition(s,a,v);if(guidance(s).en!==prev){message=guidance(s).en;translation=guidance(s).zh;}try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storage=false;}}
function say(en,zh){message=en;translation=zh;render();}
function stopSpeech(){speechRequest++;window.speechSynthesis?.cancel();}
async function speak(text,slow=false){
 if(!('speechSynthesis' in window)){notice='此浏览器不支持语音播放，可以阅读文字继续。';render();return;}
 const request=++speechRequest,synth=window.speechSynthesis;
 synth.cancel();
 const voices=await loadVoices(synth);
 if(request!==speechRequest)return;
 const voice=chooseVoice(voices,preferredVoice);
 if(!voice){notice='没有找到英语音色。请在设备中启用英语语音，或更换浏览器；暂时可用文字继续。';render();return;}
 const u=new SpeechSynthesisUtterance(text);
 u.voice=voice;u.lang=voice.lang;u.rate=slow?.85:1;u.pitch=1;u.volume=1;
 u.onerror=e=>{if(request!==speechRequest||['canceled','interrupted'].includes(e.error))return;notice='当前英语音色播放失败，请换一个音色或浏览器重试。';render();};
 synth.resume();synth.speak(u);
}
function voiceOptions(){const voices=englishVoices(window.speechSynthesis?.getVoices()||[]);return '<option value="">自动选择英语音色</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}" ${preferredVoice===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('');}
function voiceSettings(){return `<div class="voice-settings"><label for="voice-choice">英语音色</label><select id="voice-choice">${voiceOptions()}</select>${btn('试听音色','voice-preview','chip')}<small>使用设备语音，音质因设备而异；可切换音色比较。</small></div>`;}

function goal(){if(!s.started)return'在广场领取寻找 Pip 的任务';if(s.clues.length<3)return`探索校园，收集线索 ${s.clues.length}/3`;if(!s.awake)return'辨认 Pip，并根据说明唤醒它';if(!s.following)return'用英语邀请 Pip 跟你回去';if(!s.complete)return'返回科技节广场，交付任务';return'任务完成！试试新的位置挑战';}
function prep(){return `<section class="card prep"><div class="eyebrow">BEFORE THE ADVENTURE</div><h2 style="margin-top:10px">装好你的语言背包</h2><p class="muted">先认识本关会遇到的词。点卡片听发音，冒险时也能回来查看。</p>${voiceSettings()}<div class="vocabgrid">${[['🤖','robot','机器人'],['🏛️','library','图书馆'],['🌿','greenhouse','温室'],['↩','behind','在……后面'],['✨','flashing','闪烁的'],['🟢','button','按钮']].map(([i,w,z])=>`<button class="word" data-speak="${w}"><em>${i}</em><b>${w} <small>◖))</small></b><span>${z}</span></button>`).join('')}</div><div class="phrases">${['Have you seen a small robot?','Could you say that again?','Let’s check the library.'].map(t=>`<button class="phrase" data-speak="${t}">◖)) &nbsp; ${t}</button>`).join('')}</div><div class="exercise"><b>听一听，它在哪里？</b><p>播放位置描述，再选择对应地点。</p>${btn('◖)) 播放题目','quiz-audio')} ${btn('慢速重听','quiz-slow','chip')}<div class="actions" style="margin-top:12px">${btn('图书馆后面','quiz-right')}${btn('图书馆前面','quiz-wrong')}</div><p id="quiz-result" role="status">${quiz?'✓ 正确！behind 表示在后面。':''}</p></div><div class="actions">${btn('准备好了，出发 →','begin','primary',quiz?'':'disabled')}${btn(s.prepared?'返回探索':'这些已掌握，跳过准备','skip','secondary')}</div></section>`;}
function encounter(){
 const n=nearest(player);
 if(!s.prepared)return `<h2>先准备语言背包</h2>${btn('开始准备','prep','primary')}`;
 if(!n)return `<div class="encounter-idle"><b>走近人物，开始交流</b><p>方向键 / WASD 移动，或点击地面走过去。靠近有线索的人，会看到红色问号。</p><span>先到左侧广场找 Mia；点击人物也可以走到他身边。</span></div>`;
 let actions='';if(n.id==='organiser')actions=s.complete?btn('查看复盘','review','primary'):!s.started?btn('领取寻找 Pip 的任务','start','primary'):s.following?btn('把 Pip 带回展台','finish','primary'):'';
 if(n.id==='pip'&&chosen&&!s.awake)actions=btn('按绿色按钮','green','primary')+btn('按红色按钮','wrong-button');
 return `<div class="encounter-title"><span class="npc-portrait">${n.icon}</span><div><small>正在面对面交谈</small><h2>${n.name}</h2></div><span class="near-badge">● 在交谈范围内</span></div><div class="npc-response" aria-live="polite">${heardBy===n.id&&npcLine?`<strong>${esc(npcLine)}</strong>${subtitles?`<p>${esc(npcZh)}</p>`:''}`:'<strong>你想问我什么？</strong><p>点击“开口提问”，说完会自动识别并播放回答。也可以在下方打字。</p>'}</div>${lastQuestion&&heardBy===n.id?`<div class="heard">你刚才说：${esc(lastQuestion)}</div>`:''}<div class="actions">${btn(recording?'■ 结束提问':'🎙 开口提问','npc-mic','primary')}${btn('重听回答','npc-replay','secondary',heardBy===n.id&&npcLine?'':'disabled')}${actions}</div><form id="npc-talk" class="npc-form"><label for="npc-question">也可以输入英语问题</label><div><input id="npc-question" name="question" maxlength="300" placeholder="Have you seen Pip?" autocomplete="off"><button class="secondary" type="submit">提问 ↗</button></div></form><p class="muted" role="status">${esc(micError||'快捷键 E 开口提问 · 问题只发给你身边的人物')}</p>`;
}
function map(){return `<section class="card adventure"><div class="maphead"><strong>校园自由探索</strong><span class="muted">WASD / ↑↓←→ · 点击地面移动</span></div><div id="world" class="world" tabindex="0" role="group" aria-label="校园探索区域，使用方向键或 WASD 移动，E 键提问"><div class="world-path horizontal"></div><div class="world-path vertical"></div>${Object.entries(places).map(([id,p])=>`<div class="world-building" style="left:${p.x}%;top:${p.y-9}%"><span>${p.icon}</span><b>${p.name}</b></div>`).join('')}${[[8,15],[26,14],[72,13],[90,17],[9,77],[27,88],[87,81],[65,86]].map(([x,y])=>`<span class="world-tree" style="left:${x}%;top:${y}%">🌳</span>`).join('')}${NPCS.map(n=>`<button class="world-npc" data-npc="${n.id}" style="left:${n.x/10}%;top:${n.y/6}%" aria-label="走向${n.name}"><span class="quest-marker" hidden>?</span><span class="sprite">${n.icon}</span><span class="npc-name">${n.name.split(' · ')[0]}</span></button>`).join('')}<div id="destination" class="destination" hidden>◎</div><div id="player" class="world-actor player" style="left:${player.x/10}%;top:${player.y/6}%"><span>🧑‍🚀</span><small>你</small></div><div id="companion" class="world-actor follower" ${s.mode==='voice'?'hidden':''}><span>👩🏻‍🚀</span><small>Nova</small></div><div id="following-pip" class="world-actor" ${!s.following?'hidden':''}><span>🤖</span></div><div class="world-hud">${goal()}</div></div><div class="walk-controls"><span>走近红色 <b>?</b> 人物，开口获取线索</span><div>${btn('↑','walk','chip','data-value="up" aria-label="向上走"')}${btn('←','walk','chip','data-value="left" aria-label="向左走"')}${btn('↓','walk','chip','data-value="down" aria-label="向下走"')}${btn('→','walk','chip','data-value="right" aria-label="向右走"')}</div></div><section id="encounter" class="encounter">${encounter()}</section></section><div class="bottomcards"><section class="card compact"><b>◎ 当前目标</b><p>${goal()}</p><span class="muted">你来行动，Nova 只提供指导。</span></section><section class="card compact"><b>▤ 线索 ${s.clues.length} / 3</b><p>亲自询问人物，回答会自动播放。</p>${btn('打开线索本 ↗','notebook','chip')}</section></div>`;}
function refreshEncounter(){const el=document.querySelector('#encounter');if(el)el.innerHTML=encounter();}
function targetNpc(id){const n=NPCS.find(n=>n.id===id);if(!n)return;destination=bound({x:n.x-42,y:n.y+42});document.querySelector('#world')?.focus({preventScroll:true});}
function npcSubmit(text){const n=nearest(player);if(!n||!s.prepared||!text.trim())return;stopSpeech();commit('move',n.location);commit('practice');heardBy=n.id;lastQuestion=text;micError='';const r=reply(n,s,text);if(r.repeat){if(npcLine)speak(npcLine,true);else{npcLine='Ask me about Pip first.';npcZh='先问问我关于 Pip 的事情吧。';speak(npcLine);}refreshEncounter();return;}if(r.clue)commit('clue',r.clue);if(r.follow)commit('follow');if(r.reveal)chosen=true;npcLine=r.en;npcZh=r.zh;render();speak(r.en);}
function frame(time){const dt=Math.min((time-lastFrame)/1000||0,.05);lastFrame=time;
 if(view==='map'&&!document.querySelector('dialog')&&!recording){let dx=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0),dy=(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);const before={...player};if(dx||dy){destination=null;const len=Math.hypot(dx,dy);player=bound({x:player.x+dx/len*175*dt,y:player.y+dy/len*175*dt});}else if(destination){player=step(player,destination,175*dt);if(distance(player,destination)<1)destination=null;}
 if(distance(companion,player)>45)companion=step(companion,player,185*dt);
 const n=nearest(player);if(n?.id!==nearby?.id){nearby=n;chosen=false;npcLine='';npcZh='';lastQuestion='';heardBy='';micError='';refreshEncounter();}if(n&&s.location!==n.location)commit('move',n.location);
 if(distance(before,player)>.01&&time-lastSave>500){lastSave=time;try{localStorage.setItem('campus-position',JSON.stringify(player));}catch{}}
 }
 const set=(id,p)=>{const el=document.getElementById(id);if(el){el.style.left=p.x/10+'%';el.style.top=p.y/6+'%';}};set('player',player);set('companion',companion);set('following-pip',bound({x:companion.x-28,y:companion.y+30}));const dest=document.querySelector('#destination');if(dest){dest.hidden=!destination;if(destination)set('destination',destination);}
 document.querySelectorAll('.world-npc').forEach(el=>{const n=NPCS.find(n=>n.id===el.dataset.npc);const near=nearest(player)?.id===n.id;el.classList.toggle('near',near);el.classList.toggle('guide-target',n.id===guideHighlight);if(near&&n.id===guideHighlight)guideHighlight='';el.querySelector('.quest-marker').hidden=!(near&&hasInformation(n,s));});requestAnimationFrame(frame);
}
function notebook(){return `<section class="card notebook"><div class="eyebrow">FIELD NOTES</div><h2 style="margin-top:12px">我的线索本</h2><p class="muted">你亲自发现的信息，会保存在这里。</p>${s.clues.length?s.clues.map(c=>`<div class="clue"><small>0${s.clues.indexOf(c)+1} · ${clues[c][0]}</small><div>${clues[c][1]}</div><small>${clues[c][2]}</small><br><button class="chip" data-speak="${clues[c][1]}">◖)) 重听线索</button></div>`).join(''):'<div class="hero-icon">📓</div><p>还没有线索。去图书馆问问管理员吧。</p>'}${btn('返回地图','map','primary')}</section>`;}
function review(){if(!s.complete)return `<section class="card review"><h2>冒险还在继续</h2><p>${goal()}</p>${btn('继续探索','map','primary')}</section>`;return `<section class="card review"><div class="eyebrow">MISSION ACCOMPLISHED</div><div class="hero-icon">🤖 🌟</div><h2>Pip 回家了！</h2><p>你询问了目击者，连接起线索，亲手完成了任务。</p><div class="stats"><div><b>3 / 3</b><small>收集线索</small></div><div><b>${s.practice}</b><small>英语提交次数（含文字）</small></div></div><div class="clue">试着告诉 Nova：<br>“I found Pip in the greenhouse.”<br><small>也可以用自己的话，讲讲它为什么去了那里。</small></div><div class="exercise"><b>换个场景，还能听懂吗？</b><p>播放新的位置描述，再选择目的地。</p>${btn('◖)) 听新线索','transfer-audio')} ${btn('慢速重听','transfer-slow','chip')}<div class="actions" style="margin-top:14px">${btn('体育馆后面','transfer-right')}${btn('图书馆前面','transfer-wrong')}</div><p role="status">${transfer?'✓ 正确，你理解了新地点的位置关系。':''}</p></div><p class="muted">原型不评估发音或语言等级。这里展示的是实际任务与练习记录。</p>${btn('再玩一次','reset','primary')}</section>`;}
function welcome(){const g=guidance(s);return `<section class="card welcome"><div class="eyebrow">YOUR COMPANION · NOVA</div><div class="welcome-portrait">👩🏻‍🚀</div><h2>${s.started?'欢迎回来，我们继续找 Pip':'嗨，我是 Nova。一起开始冒险吧！'}</h2><p class="welcome-story">校园科技节就要开始了，迎宾机器人 Pip 却不见了。你负责探索和寻找，我会陪你同行，帮你理解线索。</p><div class="opening-plan"><small>我们接下来这样做</small><p>${g.zh}</p></div>${btn(s.started?'听教练提醒，继续冒险 →':'听教练介绍，开始冒险 →','welcome-start','primary')}<p class="muted">点一次开始即可听介绍，无需开启麦克风。随时可静音或重听。</p></section>`;}
function planBanner(){const g=guidance(s);return `<div class="plan-banner"><span>👩🏻‍🚀</span><div><small>NOVA · 下一步</small><p>${g.zh}</p></div>${btn('和教练交谈','coach-talk','primary')}</div>`;}
function coach(){const g=guidance(s);return `<aside class="card coachpanel" id="coach-panel"><div class="coachhead"><div class="avatar">👩🏻‍🚀</div><div><strong>Nova <span class="muted">/ 你的同行教练</span></strong><div class="online">● 随时可以问我 · 脚本原型</div></div></div><div class="modes">${btn('♧ 同行陪伴','mode',s.mode==='companion'?'active':'','data-value="companion"')}${btn('◖)) 语音陪伴','mode',s.mode==='voice'?'active':'','data-value="voice"')}</div><div class="conversation"><div class="bubble" aria-live="polite">${esc(message)}${subtitles?`<div class="translation">${esc(translation)}</div>`:''}</div><div class="tools">${btn('◖)) 重听','listen')}${btn('慢速','slow')}${btn('停止','stop')}${btn(subtitles?'隐藏中文':'显示中文','subtitle')}</div><div class="coach-quick">${btn(recording?'■ 结束交谈':'🎙 和教练交谈','coach-talk','primary')}${btn('下一步做什么？','coach-next','secondary')}${btn('这句话怎么说？','phrase-help','secondary')}${btn(g.cta,'guide-target','chip')}</div></div><div class="composer"><p class="status" id="voice-status" role="status">${esc(coachStatus||'说完自动回答，不需要再点发送。也可直接点上面的常用问题。')}</p><details><summary>打字问教练（支持中文）</summary><form id="talk"><label for="utterance">有不清楚的地方，直接问我</label><input id="utterance" name="utterance" autocomplete="off" maxlength="300" placeholder="不知道下一步该做什么" aria-label="向教练提问"><button type="submit" class="secondary">发送 ↗</button></form></details></div></aside>`;}
function render(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">campus<span>quest.</span><small>英语同行冒险</small></div><nav class="nav" aria-label="主导航">${[['map','◈ 冒险地图'],['prep','▧ 语言背包'],['notebook','▤ 线索手记'],['review','☆ 冒险回顾']].map(([v,t])=>btn(t,v,view===v?'active':'')).join('')}</nav><div class="side-note">YOUR ADVENTURE<br><b>每一次开口，<br>都是新的发现。</b><br>你来探索，教练与你同行。</div></aside><main class="workspace"><div class="topbar"><span>探索营地 &nbsp; / &nbsp; 校园篇 &nbsp; / &nbsp; 第 01 关</span><span class="pill">🌱 A1–A2 · 入门探索员</span></div><header class="heading"><div><div class="eyebrow">THE MISSING ROBOT</div><h1>消失的科技节机器人</h1><p>跟随线索，找到 Pip。校园里的冒险，从你开口开始。</p></div><span class="pill">◷ 约 20 分钟 · 无倒计时</span></header>${!storage?'<div class="toast">浏览器存储不可用，本次进度仅保留到页面关闭。</div>':''}${notice?`<div class="toast" role="status">${esc(notice)}</div>`:''}<div class="layout"><div>${view==='welcome'?welcome():view==='prep'?prep():view==='notebook'?notebook():view==='review'?review():planBanner()+map()}</div>${coach()}</div><footer class="footnote"><span>EPISODE 01 · GREENFIELD CAMPUS</span><span>进度保存在此浏览器 · 脚本互动，不含真人联机 &nbsp; ${btn('重置进度','reset','chip')}</span></footer></main></div>`;}
function focusInput(){document.querySelector('#utterance')?.focus();}
function submit(text){if(!text.trim())return;if(/repeat|again|slow|再说|重听/i.test(text)){speak(message,true);return;}const answer=coachAnswer(s,text);coachStatus='';say(answer.en,answer.zh);speak(answer.en);}
function action(a,v){notice='';
if(a==='welcome-start'){view=s.complete?'review':s.prepared?'map':'prep';const g=guidance(s);say(g.en,g.zh);speak(g.en);return;}
if(a==='coach-next'||a==='hint'){submit('下一步做什么');return;}
if(a==='coach-talk'){mic('coach');return;}
if(a==='guide-target'){const g=guidance(s);if(g.view){view=g.view;render();}else{view='map';guideHighlight=g.target;render();document.querySelector('#world')?.scrollIntoView({block:'center',behavior:'smooth'});}return;}

if(a==='walk'){const d={up:[0,-90],down:[0,90],left:[-90,0],right:[90,0]}[v];destination=bound({x:player.x+d[0],y:player.y+d[1]});return;}
if(a==='npc-mic'){mic('npc');return;}
if(a==='npc-replay'){if(npcLine)speak(npcLine);return;}
if(['start','finish','green','wrong-button'].includes(a)){const n=nearest(player);if(!n||(['start','finish'].includes(a)?n.id!=='organiser':n.id!=='pip'))return;commit('move',n.location);}
if(['map','prep','notebook','review'].includes(a)){keys.clear();destination=null;recording?.abort();recording=null;stopSpeech();view=a;render();return;}if(a==='move'){const n=NPCS.find(n=>n.location===v);if(n)targetNpc(n.id);return;}if(a==='mode'){commit('mode',v);render();return;}if(a==='begin'||a==='skip'){commit('prepare');view='map';guideHighlight='organiser';const g=guidance(s);say(g.en,g.zh);speak(g.en);return;}if(a==='start'){commit('start');heardBy='organiser';lastQuestion='';npcLine='Pip is a small white robot with a blue light. Ask Ben at the library if he has seen it.';npcZh='Pip 是白色小机器人，有蓝色灯。去图书馆问问 Ben。';render();speak(npcLine);return;}if(a==='brief'){say('Pip is a small white robot. It has a blue light.','Pip 是白色小机器人，有一盏蓝灯。');return;}if(a==='record'){commit('clue','record');say('The note says: blue light flashing. Pip flashes blue when it follows something bright.','设备记录已收集：蓝灯闪烁。Pip 追逐明亮的物品时会闪蓝灯。');return;}if(a==='ask-library'||a==='ask-art'||a==='ask-follow'){say(a==='ask-library'?'The librarian is listening. What would you like to ask?':a==='ask-art'?'The art club member is here. Ask where the decoration went.':'Pip is ready. Tell it to come with you.',a==='ask-library'?'管理员在听。试着问她是否见过机器人。':a==='ask-art'?'美术社成员就在这里，问问装饰物去了哪里。':'Pip 准备好了，用英语邀请它跟你走。');focusInput();return;}if(a==='example-library'){speak('Have you seen a small robot?');return;}if(a==='gym'){say('I haven’t seen a robot here. Try asking at the library.','工作人员说这里没见过机器人，可以去图书馆问问。');return;}if(a==='blue'){if(s.clues.length<3){say('We need more evidence. Let’s check our notes before choosing.','还需要收集三条线索，才能确认目标。');return;}chosen=true;say('That’s Pip! Press the green button, then wait for the blue light.','找到 Pip 了！按绿色按钮，等待蓝灯亮起。');return;}if(a==='red'||a==='wrong-button'){say('Take another look. What colour did the instructions mention?','再想一想，描述或说明里提到的是哪种颜色？可以重听。');return;}if(a==='green'&&chosen){commit('wake');heardBy='pip';npcLine='I’m awake! Ask me to come with you.';npcZh='我醒了！邀请我跟你一起走吧。';render();speak(npcLine);return;}if(a==='finish'){commit('finish');if(s.complete){view='review';say('You did it! Where did you find Pip?','你完成了任务！试着用英语讲讲在哪里找到了 Pip。');}return;}if(a==='voice-preview'){speak('Hello! The robot is behind the library.');return;}if(a==='quiz-audio'||a==='quiz-slow'){speak('The robot is behind the library.',a==='quiz-slow');return;}if(a==='quiz-right'){quiz=true;notice='听辨正确！也可以在右侧试着说一句 Have you seen a small robot?';render();return;}if(a==='quiz-wrong'){notice='再听一次，注意 behind。可以反复尝试。';render();return;}if(a==='transfer-audio'||a==='transfer-slow'){speak('The robot is behind the gym.',a==='transfer-slow');return;}if(a==='transfer-right'){transfer=true;notice='正确！这次地点换成了体育馆。';render();return;}if(a==='transfer-wrong'){notice='再听一次，注意 gym 和 behind。';render();return;}if(a==='listen'||a==='slow'){speak(message,a==='slow');return;}if(a==='stop'){stopSpeech();return;}if(a==='subtitle'){subtitles=!subtitles;render();return;}if(a==='phrase-help'){submit('这句话怎么说');return;}if(a==='hint'){const h=!s.started?['Where does our mission start?','Look for the festival organiser.','Go to the plaza and collect the mission.']:s.clues.length<3?['What evidence do we have so far?','A witness and the art room may help.','Ask the librarian about Pip. Check the art room note and ask about the decoration.']:!s.awake?['What does Pip look like?','Remember the blue light.','Visit the greenhouse, select the blue-light robot, and press the green button.']:!s.following?['Pip is ready to move.','How can you invite it along?','Try saying: Follow me, Pip.']:['Where did we start?','The festival needs Pip back.','Return to the plaza and hand in the mission.'];say(h[Math.min(hint++,2)],`提示 ${Math.min(hint,3)}/3 · ${goal()}。由你决定并完成操作。`);return;}if(a==='mic'){mic('coach');return;}if(a==='reset'){const d=document.createElement('dialog');d.innerHTML='<h2>重新开始冒险？</h2><p>这会清除本浏览器里的当前关卡进度。</p><div class="actions"><button class="secondary" id="cancel-reset">继续冒险</button><button class="primary" id="confirm-reset">确认重置</button></div>';document.body.append(d);d.showModal();d.querySelector('#cancel-reset').onclick=()=>d.remove();d.querySelector('#confirm-reset').onclick=()=>{recording?.abort();recording=null;stopSpeech();s=initial();player={x:150,y:460};companion={x:115,y:480};destination=null;keys.clear();nearby=null;npcLine='';npcZh='';heardBy='';lastQuestion='';try{localStorage.removeItem('campus-position');localStorage.removeItem(KEY);}catch{}view='welcome';quiz=false;transfer=false;chosen=false;hint=0;guideHighlight='';coachStatus='';d.remove();const g=guidance(s);say(g.en,g.zh);};return;}}
function mic(target='npc'){
 if(recording){recording.stop();return;}
 const R=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!R){if(target==='coach'){coachStatus='此浏览器不支持语音，请点常用问题，或展开下面的文字提问。';render();document.querySelector('#coach-panel')?.scrollIntoView({block:'center'});}else{micError='当前浏览器不支持语音识别，请输入英语问题；提交后人物仍会自动播放回答。';refreshEncounter();}return;}
 const n=nearest(player);if(target==='npc'&&(!n||!s.prepared))return;
 const start=()=>{micApproved=true;stopSpeech();destination=null;keys.clear();micError='正在听你提问，说完自动识别并回答…';const r=new R();recording=r;if(target==='coach'){coachStatus='正在听你说话…说完会自动回答。';render();}r.lang='en-US';r.interimResults=false;r.continuous=false;refreshEncounter();
 r.onresult=e=>{const text=e.results[0][0].transcript;recording=null;r.stop();if(target==='npc'&&view==='map'&&nearest(player)?.id===n.id)npcSubmit(text);else if(target==='coach'){submit(text);}};
 r.onerror=e=>{micError=e.error==='not-allowed'?'麦克风权限未开启，可以输入英语问题。':'没有听清，请再问一次，也可以输入文字。';};
 r.onend=()=>{recording=null;if(micError.startsWith('正在听'))micError='未收到问题，请再次点击开口提问。';if(target==='coach'){if(coachStatus.startsWith('正在听'))coachStatus=micError;render();}else refreshEncounter();};
 try{r.start();}catch{recording=null;micError='语音无法启动，请使用文字提问。';if(target==='coach'){coachStatus=micError;render();}else refreshEncounter();}};
 if(micApproved){start();return;}
 const d=document.createElement('dialog');d.innerHTML='<h2>开启语音交谈</h2><p>说完后自动识别问题，对方会直接播放回答。浏览器可能使用其远程语音服务；本应用不保存录音。</p><div class="actions"><button class="secondary" id="no-mic">改用文字</button><button class="primary" id="yes-mic">开启麦克风</button></div>';document.body.append(d);d.showModal();d.querySelector('#no-mic').onclick=()=>{d.remove();if(target==='coach'){document.querySelector('#coach-panel details').open=true;document.querySelector('#utterance')?.focus();}else document.querySelector('#npc-question')?.focus();};d.querySelector('#yes-mic').onclick=()=>{d.remove();start();};
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.speak){speak(b.dataset.speak);return;}if(b.dataset.action)action(b.dataset.action,b.dataset.value);});document.addEventListener('submit',e=>{if(e.target.id==='npc-talk'){e.preventDefault();npcSubmit(new FormData(e.target).get('question')||'');return;}if(e.target.id!=='talk')return;e.preventDefault();submit(new FormData(e.target).get('utterance')||'');});render();

document.addEventListener('change',e=>{if(e.target.id==='voice-choice'){stopSpeech();preferredVoice=e.target.value;try{localStorage.setItem('campus-voice',preferredVoice);}catch{}}});
window.speechSynthesis?.addEventListener('voiceschanged',()=>{const select=document.querySelector('#voice-choice');if(select)select.innerHTML=voiceOptions();});

document.addEventListener('click',e=>{const world=e.target.closest('#world');if(!world||view!=='map'||recording)return;const npc=e.target.closest('[data-npc]');if(npc){targetNpc(npc.dataset.npc);return;}const rect=world.getBoundingClientRect();destination=bound({x:(e.clientX-rect.left)/rect.width*1000,y:(e.clientY-rect.top)/rect.height*600});world.focus({preventScroll:true});});
document.addEventListener('keydown',e=>{if(view!=='map'||document.querySelector('dialog')||e.target.closest('input,textarea,select,[contenteditable=true]'))return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(k)){if(recording)return;e.preventDefault();if(!e.repeat){const d={arrowup:[0,-8],w:[0,-8],arrowdown:[0,8],s:[0,8],arrowleft:[-8,0],a:[-8,0],arrowright:[8,0],d:[8,0]}[k];player=bound({x:player.x+d[0],y:player.y+d[1]});destination=null;}keys.add(k);}if(k==='e'&&!e.repeat&&s.prepared&&nearest(player)){e.preventDefault();mic('npc');}});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();destination=null;});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();destination=null;}});requestAnimationFrame(frame);

document.addEventListener('focusin',e=>{if(e.target.closest('input,textarea,select')){keys.clear();destination=null;}});
